20	/// Export a page into a raster image.
21	///
22	/// This renders the page at the given number of pixels per inch and returns
23	/// the resulting `tiny-skia` pixel buffer.
24	#[typst_macros::time(name = "render")]
25	pub fn render(page: &Page, opts: &RenderOptions<Complete>) -> sk::Pixmap {
26	    let bleed = if opts.render_bleed { page.bleed } else { Sides::default() };
27	
28	    let size = page.frame.size() + bleed.sum_by_axis();
29	    let pixel_per_pt = opts.format.ppi.v.get() as f32 / 72.0;
30	    let pxw = (pixel_per_pt * size.x.to_f32()).round().max(1.0) as u32;
31	    let pxh = (pixel_per_pt * size.y.to_f32()).round().max(1.0) as u32;
32	
33	    let ts = sk::Transform::from_scale(pixel_per_pt, pixel_per_pt);
34	    let state = State::new(size, ts, pixel_per_pt);
35	
36	    let mut canvas = sk::Pixmap::new(pxw, pxh).unwrap();
37	
38	    if let Some(fill) = page.fill_or_white() {
39	        if let Paint::Solid(color) = fill {
40	            canvas.fill(paint::to_sk_color(color.to_process()));
41	        } else {
42	            let rect = Geometry::Rect(size).filled(fill);
43	            shape::render_shape(&mut canvas, state, &rect);
44	        }
45	    }
46	
47	    let state = state.pre_translate(Point { x: bleed.left, y: bleed.top });
48	
49	    render_frame(&mut canvas, state, &page.frame);
50	
51	    canvas
52	}
