219	                    .post_concat(state.container_transform.invert().unwrap()),
220	            )
221	            .pre_concat_container(to_sk_transform(&Transform::translate(pos.x, pos.y)))
222	            .pre_concat_container(sk_transform)
223	            .with_size(group.frame.size()),
224	    };
225	
226	    let mut mask = state.mask;
227	    let storage;
228	    if let Some(clip_curve) = group.clip.as_ref()
229	        && let Some(path) = shape::convert_curve(clip_curve)
230	            .and_then(|path| path.transform(state.transform))
231	    {
232	        if let Some(mask) = mask {
233	            let mut mask = mask.clone();
234	            mask.intersect_path(
235	                &path,
236	                sk::FillRule::default(),
237	                true,
238	                sk::Transform::default(),
239	            );
240	            storage = mask;
241	        } else {
242	            let pxw = canvas.width();
243	            let pxh = canvas.height();
244	            let Some(mut mask) = sk::Mask::new(pxw, pxh) else {
245	                // Fails if clipping rect is empty. In that case we just
246	                // clip everything by returning.
247	                return;
248	            };
249	
250	            mask.fill_path(
251	                &path,
252	                sk::FillRule::default(),
253	                true,
254	                sk::Transform::default(),
255	            );
256	            storage = mask;
257	        }
258	
259	        mask = Some(&storage);
260	    }
261	
262	    render_frame(canvas, state.with_mask(mask), &group.frame);
263	}
