266	    let Transform { sx, ky, kx, sy, tx, ty } = *transform;
267	    sk::Transform::from_row(
268	        sx.get() as f32,
269	        ky.get() as f32,
270	        kx.get() as f32,
271	        sy.get() as f32,
272	        tx.to_f32(),
