33	/// Export a frame into an SVG file.
34	#[typst_macros::time(name = "svg")]
35	pub fn svg(page: &Page, opts: &SvgOptions<Complete>) -> String {
36	    let (size, ts) = page_bleed(page, opts);
37	
38	    let mut renderer = SVGRenderer::new();
39	    let mut xml = XmlWriter::new(xml_options(opts.format.pretty.v));
40	    let mut svg = svg_header(&mut xml, size);
41	
42	    let state = State::new(size);
43	    renderer.render_page(&mut svg, &state, ts, page);
44	    renderer.finalize(svg);
45	    xml.end_document()
46	}
47	
48	/// Export a page into an SVG file as part of a bundle.
49	///
50	/// Takes additional `anchor` locations that will be serialized as linkable
51	/// points. This enables other documents in the bundle to link into the
52	/// resulting SVG. Also takes a `link_resolver` for resolving cross-document
53	/// links.
54	#[typst_macros::time(name = "svg in bundle")]
55	pub fn svg_in_bundle(
56	    page: &Page,
57	    opts: &SvgOptions<Complete>,
58	    anchors: &[(Point, EcoString)],
59	    link_resolver: Tracked<LateLinkResolver>,
60	) -> String {
61	    let (size, ts) = page_bleed(page, opts);
62	
63	    let mut renderer = SVGRenderer::with_options(Some(link_resolver));
64	    let mut xml = XmlWriter::new(xml_options(opts.format.pretty.v));
65	    let mut svg = svg_header(&mut xml, size);
66	
67	    let state = State::new(size);
68	    renderer.render_page(&mut svg, &state, ts, page);
69	
70	    for (pos, id) in anchors {
71	        renderer.render_anchor(&mut svg, *pos, id);
72	    }
73	
74	    renderer.finalize(svg);
75	    xml.end_document()
76	}
77	
78	/// Export a frame into an SVG suitable for embedding into HTML.
79	///
80	/// Takes additional `anchor` locations that will be serialized as linkable
81	/// points. This enables other documents in the bundle to link into the
82	/// resulting SVG. Also takes a `link_resolver` for resolving links between the
83	/// frame and remaining document.
84	#[typst_macros::time(name = "svg in html")]
85	pub fn svg_in_html(
86	    frame: &Frame,
87	    text_size: Abs,
88	    pretty: bool,
89	    id: Option<&str>,
90	    styles: &str,
91	    anchors: &[(Point, EcoString)],
92	    link_resolver: Tracked<LateLinkResolver>,
93	) -> String {
94	    let mut renderer = SVGRenderer::with_options(Some(link_resolver));
95	    let mut xml = XmlWriter::new(xml_options(pretty));
96	    let mut svg = svg_header_with_custom_attrs(&mut xml, frame.size(), |svg| {
97	        if let Some(id) = id {
98	            svg.attr("id", id);
99	        }
100	        svg.attr_with("style", |attr| {
101	            // TODO: Maybe make this a little more elegant?
102	            attr.push_str("overflow: visible; width: ");
103	            attr.push_num(frame.width() / text_size);
104	            attr.push_str("em; height: ");
105	            attr.push_num(frame.height() / text_size);
106	            attr.push_str("em;");
107	            if !styles.is_empty() {
108	                attr.push_str(" ");
109	                attr.push_str(styles);
110	            }
111	        });
112	    });
113	
114	    let state = State::new(frame.size());
115	    renderer.render_frame(&mut svg, &state, frame);
116	
117	    for (pos, id) in anchors {
118	        renderer.render_anchor(&mut svg, *pos, id);
119	    }
120	
121	    renderer.finalize(svg);
122	    xml.end_document()
123	}
124	
125	/// Export a document with potentially multiple pages into a single SVG file.
126	///
127	/// The gap will be added between the individual pages.
128	pub fn svg_merged(document: &PagedDocument, opts: &SvgOptions, gap: Abs) -> String {
129	    let opts = opts.resolve(document.options().get::<SvgFormat>());
130	    let num_gaps = document.pages().len().saturating_sub(1) as f64;
131	    let mut size = Size::new(Abs::zero(), num_gaps * gap);
132	    for page in document.pages() {
133	        let (page_size, _ts) = page_bleed(page, &opts);
134	        size.x.set_max(page_size.x);
135	        size.y += page_size.y;
136	    }
137	
138	    let mut renderer = SVGRenderer::new();
139	    let mut xml = XmlWriter::new(xml_options(opts.format.pretty.v));
140	    let mut svg = svg_header(&mut xml, size);
141	
142	    let mut y = Abs::zero();
143	    for page in document.pages() {
144	        let (page_size, bleed_ts) = page_bleed(page, &opts);
145	        let state = State::new(page_size);
146	        renderer.render_page(
147	            &mut svg,
148	            &state,
149	            Transform::translate(Abs::zero(), y).pre_concat(bleed_ts),
150	            page,
151	        );
152	        y += page_size.y + gap;
153	    }
154	
155	    renderer.finalize(svg);
156	    xml.end_document()
157	}
158	
159	fn page_bleed(page: &Page, opts: &SvgOptions<Complete>) -> (Size, Transform) {
160	    let bleed = if opts.render_bleed { page.bleed } else { Sides::default() };
161	    let size = page.frame.size() + bleed.sum_by_axis();
162	    let ts = Transform::translate(bleed.left, bleed.top);
163	    (size, ts)
164	}
165	
166	fn xml_options(pretty: bool) -> xmlwriter::Options {
167	    xmlwriter::Options {
168	        use_single_quote: false,
169	        indent: if pretty {
170	            xmlwriter::Indent::Spaces(2)
171	        } else {
172	            xmlwriter::Indent::None
173	        },
174	        attributes_indent: xmlwriter::Indent::None,
175	    }
176	}
177	
178	/// Settings for SVG export.
179	#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
180	pub struct SvgOptions<F: Fields = Partial> {
181	    /// By default, SVG documents are bounded to the page size. In some
182	    /// circumstances, such as when preparing documents for print, it may be
183	    /// desirable to include content beyond these bounds to account for bleed
184	    /// margins. This field allows expanding the document area to include such
185	    /// bleed.
186	    pub render_bleed: bool,
187	    /// Format options that override the defaults set by the document.
188	    pub format: SvgFormatOptions<F>,
189	}
190	
191	impl SvgOptions<Partial> {
192	    /// Resolves the final options given those set by the document.
193	    pub fn resolve(&self, doc: &SvgFormatOptions) -> SvgOptions<Complete> {
194	        SvgOptions {
195	            render_bleed: self.render_bleed,
196	            format: self.format.resolve(doc),
197	        }
198	    }
199	}
200	
201	/// Renders one or multiple frames to an SVG file.
202	struct SVGRenderer<'a> {
203	    /// The document's introspector, if we're writing an HTML frame.
204	    link_resolver: Option<Tracked<'a, LateLinkResolver<'a>>>,
205	    /// Prepared glyphs.
206	    glyphs: Deduplicator<Option<RenderedGlyph>>,
207	    /// Clip paths are used to clip a group. A clip path is a path that defines
208	    /// the clipping region. The clip path is referenced by the `clip-path`
209	    /// attribute of the group. The clip path is in the format of `M x y L x y C
210	    /// x1 y1 x2 y2 x y Z`.
211	    clip_paths: Deduplicator<EcoString>,
212	    /// These are the actual gradients being written in the SVG file.
213	    /// These gradients are deduplicated because they do not contain the transform
214	    /// matrix, allowing them to be reused across multiple invocations.
215	    ///
216	    /// The `Ratio` is the aspect ratio of the gradient, this is used to correct
217	    /// the angle of the gradient.
218	    gradients: Deduplicator<(Gradient, Ratio)>,
219	    /// Deduplicated gradients with transform matrices. They use a reference
220	    /// (`href`) to a "source" gradient instead of being defined inline.
221	    /// This saves a lot of space since gradients are often reused but with
222	    /// different transforms. Therefore this allows us to reuse the same gradient
223	    /// multiple times.
224	    gradient_refs: Deduplicator<GradientRef>,
225	    /// These are the gradients that compose a conic gradient.
226	    conic_subgradients: Deduplicator<SVGSubGradient>,
227	    /// These are the actual tilings being written in the SVG file.
228	    /// These tilings are deduplicated because they do not contain the transform
229	    /// matrix, allowing them to be reused across multiple invocations.
230	    ///
231	    /// The `String` is the rendered tiling frame.
232	    tilings: Deduplicator<Tiling>,
233	    /// Deduplicated tilings with transform matrices. They use a reference
234	    /// (`href`) to a "source" tiling instead of being defined inline.
235	    /// This saves a lot of space since tilings are often reused but with
236	    /// different transforms. Therefore this allows us to reuse the same gradient
237	    /// multiple times.
238	    tiling_refs: Deduplicator<TilingRef>,
239	}
240	
241	/// Contextual information for rendering.
242	#[derive(Copy, Clone)]
243	struct State {
244	    /// The transform of the current item.
245	    transform: Transform,
246	    /// The size of the first hard frame in the hierarchy.
247	    size: Size,
248	}
249	
250	impl State {
251	    fn new(size: Size) -> Self {
252	        Self { size, transform: Transform::identity() }
253	    }
254	
255	    /// Pre translate the current item's transform.
256	    fn pre_translate(self, pos: Point) -> Self {
257	        self.pre_concat(Transform::translate(pos.x, pos.y))
258	    }
259	
260	    /// Pre concat the current item's transform.
261	    fn pre_concat(self, transform: Transform) -> Self {
262	        Self {
263	            transform: self.transform.pre_concat(transform),
264	            ..self
265	        }
266	    }
267	
268	    /// Sets the size of the first hard frame in the hierarchy.
269	    fn with_size(self, size: Size) -> Self {
270	        Self { size, ..self }
271	    }
272	
273	    /// Sets the current item's transform.
274	    fn with_transform(self, transform: Transform) -> Self {
275	        Self { transform, ..self }
276	    }
277	}
278	
279	impl<'a> SVGRenderer<'a> {
280	    /// Create a new SVG renderer with empty glyph and clip path.
281	    fn new() -> Self {
282	        Self::with_options(None)
283	    }
284	
285	    /// Create a new SVG renderer with the given configuration.
286	    fn with_options(link_resolver: Option<Tracked<'a, LateLinkResolver<'a>>>) -> Self {
287	        SVGRenderer {
288	            link_resolver,
289	            glyphs: Deduplicator::new('g'),
290	            clip_paths: Deduplicator::new('c'),
291	            gradients: Deduplicator::new('f'),
292	            gradient_refs: Deduplicator::new('r'),
293	            conic_subgradients: Deduplicator::new('s'),
294	            tilings: Deduplicator::new('t'),
295	            tiling_refs: Deduplicator::new('p'),
296	        }
297	    }
298	
299	    /// Render a page with the given transform.
300	    fn render_page(
301	        &mut self,
302	        svg: &mut SvgElem,
303	        state: &State,
304	        ts: Transform,
305	        page: &Page,
306	    ) {
307	        let mut svg = svg.lazy_elem("g");
308	        if !ts.is_identity() {
309	            svg.init().attr("transform", SvgTransform(ts));
310	        }
311	
312	        if let Some(fill) = page.fill_or_white() {
313	            let shape =
314	                Geometry::Rect(page.frame.size() + page.bleed.sum_by_axis()).filled(fill);
315	            let state =
316	                &state.pre_translate(Point { x: -page.bleed.left, y: -page.bleed.top });
317	            self.render_shape(svg.lazy(), state, &shape);
318	        }
319	
320	        self.render_frame(svg.lazy(), state, &page.frame);
321	    }
322	
323	    /// Render a frame with the given transform.
324	    fn render_frame(&mut self, svg: &mut SvgElem, state: &State, frame: &Frame) {
325	        for (pos, item) in frame.items() {
326	            let state = state.pre_translate(*pos);
327	            match item {
328	                FrameItem::Group(group) => self.render_group(svg, &state, group),
329	                FrameItem::Text(text) => self.render_text(svg, &state, text),
330	                FrameItem::Shape(shape, _) => self.render_shape(svg, &state, shape),
331	                FrameItem::Image(image, size, _) => {
332	                    self.render_image(svg, &state, image, size);
333	                }
334	                FrameItem::Link(dest, size) => self.render_link(svg, &state, dest, *size),
335	                FrameItem::Tag(_) => {}
336	            }
337	        }
338	    }
339	
340	    /// Render a group. If the group has `clips` set to true, a clip path will
341	    /// be created.
342	    fn render_group(&mut self, svg: &mut SvgElem, state: &State, group: &GroupItem) {
343	        let mut svg = svg.lazy_elem("g");
344	
345	        let state = match group.frame.kind() {
346	            FrameKind::Soft => state.pre_concat(group.transform),
347	            FrameKind::Hard => {
348	                // Always generate a group for hard frames.
349	                svg.init();
350	
351	                let transform = state.transform.pre_concat(group.transform);
352	                if !transform.is_identity() {
353	                    svg.init().attr("transform", SvgTransform(transform));
354	                }
355	                state
356	                    .with_transform(Transform::identity())
357	                    .with_size(group.frame.size())
358	            }
359	        };
360	
361	        if let Some(label) = group.label {
362	            svg.init().attr("data-typst-label", label.resolve());
363	        }
364	
365	        if let Some(clip_curve) = &group.clip {
366	            let offset = Point::new(state.transform.tx, state.transform.ty);
367	            let id = self.clip_paths.insert_with((clip_curve, offset), || {
368	                shape::convert_curve(offset, clip_curve)
369	            });
370	            svg.init().attr("clip-path", SvgUrl(id));
371	        }
372	
373	        self.render_frame(svg.lazy(), &state, &group.frame);
374	    }
375	
376	    /// Render a link element.
377	    fn render_link(
378	        &mut self,
379	        svg: &mut SvgElem,
380	        state: &State,
381	        dest: &Destination,
382	        size: Size,
383	    ) {
384	        let mut a = svg.elem("a");
385	        if !state.transform.is_identity() {
386	            a.attr("transform", SvgTransform(state.transform));
387	        }
388	
389	        match dest {
390	            Destination::Url(url) => {
391	                a.attr("href", url.as_str());
392	                a.attr("xlink:href", url.as_str());
393	            }
394	            Destination::Position(_) => {
395	                // TODO: Links on the same page could be supported.
396	            }
397	            Destination::Location(loc) => {
398	                // TODO: Location links on the same page could also be supported
399	                // outside of HTML.
400	                if let Some(resolver) = self.link_resolver
401	                    && let Some(link) = resolver.resolve(*loc)
402	                    && let Ok(uri) = link.into_relative_uri()
403	                {
404	                    a.attr("href", &uri);
405	                    a.attr("xlink:href", &uri);
406	                }
407	            }
408	        }
409	
410	        a.elem("rect")
411	            .attr("width", size.x.to_pt())
412	            .attr("height", size.y.to_pt())
413	            .attr("fill", "transparent")
414	            .attr("stroke", "none");
415	    }
416	
417	    /// Renders a linkable point that can be used to link into an HTML frame.
418	    fn render_anchor(&mut self, svg: &mut SvgElem, pos: Point, id: &str) {
419	        svg.elem("g")
420	            .attr("id", id)
421	            .attr("transform", SvgTransform(Transform::translate(pos.x, pos.y)));
422	    }
423	
424	    /// Finalize the SVG file. This must be called after all rendering is done.
425	    fn finalize(mut self, mut svg: SvgElem) {
426	        self.write_glyph_defs(&mut svg);
427	        self.write_clip_path_defs(&mut svg);
428	        self.write_gradients(&mut svg);
429	        self.write_gradient_refs(&mut svg);
430	        self.write_subgradients(&mut svg);
431	        self.write_tilings(&mut svg);
432	        self.write_tiling_refs(&mut svg);
433	    }
434	
435	    /// Build the clip path definitions.
436	    fn write_clip_path_defs(&self, svg: &mut SvgElem) {
437	        if self.clip_paths.is_empty() {
438	            return;
439	        }
440	
441	        let mut defs = svg.elem("defs");
442	        for (id, path) in self.clip_paths.iter() {
443	            defs.elem("clipPath").attr("id", id).with(|svg| {
444	                svg.elem("path").attr("d", path);
445	            });
446	        }
447	    }
448	}
449	
450	/// Write the default SVG header, including a `typst-doc` class, the
451	/// `viewBox` and `width` and `height` attributes.
452	fn svg_header(xml: &mut XmlWriter, size: Size) -> SvgElem<'_> {
453	    svg_header_with_custom_attrs(xml, size, |_| {})
454	}
455	
456	/// Write the SVG header with additional attributes and standard attributes.
457	fn svg_header_with_custom_attrs(
458	    xml: &mut XmlWriter,
459	    size: Size,
460	    write_custom_attrs: impl FnOnce(&mut SvgElem),
461	) -> SvgElem<'_> {
462	    // Clamp the size of SVGs to at least one pt. resvg and probably also
463	    // other SVG parsers don't handle SVGs with 0 sized dimensions.
464	    let size = size.max(Size::splat(Abs::pt(1.0)));
465	
466	    let mut svg = SvgElem::new(xml, "svg");
467	
468	    write_custom_attrs(&mut svg);
469	
470	    svg.attr_with("viewBox", |attr| {
471	        attr.push_nums([0.0, 0.0, size.x.to_pt(), size.y.to_pt()]);
472	    });
473	    svg.attr_with("width", |attr| {
474	        attr.push_num(size.x.to_pt());
475	        attr.push_str("pt");
476	    });
477	    svg.attr_with("height", |attr| {
478	        attr.push_num(size.y.to_pt());
479	        attr.push_str("pt");
480	    });
481	    svg.attr("xmlns", "http://www.w3.org/2000/svg");
482	    svg.attr("xmlns:xlink", "http://www.w3.org/1999/xlink");
483	    svg.attr("xmlns:h5", "http://www.w3.org/1999/xhtml");
484	
485	    svg
486	}
487	
488	/// Deduplicates its elements. It is used to deduplicate glyphs and clip paths.
489	/// The `H` is the hash type, and `T` is the value type. The `PREFIX` is the
490	/// prefix of the index. This is used to distinguish between glyphs and clip
491	/// paths.
492	#[derive(Debug, Default, Clone)]
493	struct Deduplicator<T> {
494	    kind: char,
495	    map: IndexMap<u128, T, FxBuildHasher>,
496	}
497	
498	impl<T> Deduplicator<T> {
499	    fn new(kind: char) -> Self {
500	        Self { kind, map: IndexMap::default() }
501	    }
502	
503	    /// Inserts a value into the vector. If the hash is already present, returns
504	    /// the index of the existing value and `f` will not be called. Otherwise,
505	    /// inserts the value and returns the id of the inserted value.
506	    #[must_use = "returns the id of the inserted value"]
507	    fn insert_with<K, F>(&mut self, key: K, f: F) -> DedupId
508	    where
509	        K: Hash,
510	        F: FnOnce() -> T,
511	    {
512	        self.insert_with_val(key, f).0
513	    }
514	
515	    /// Same as [`Self::insert_with`], but it also returns a reference to the
516	    /// cached or inserted value.
517	    #[must_use]
518	    fn insert_with_val<K, F>(&mut self, key: K, f: F) -> (DedupId, &mut T)
519	    where
520	        K: Hash,
521	        F: FnOnce() -> T,
522	    {
523	        let hash = typst_utils::hash128(&key);
524	        let val = self.map.entry(hash).or_insert_with(f);
525	        (DedupId(self.kind, hash), val)
526	    }
527	
528	    /// Iterate over the elements alongside their ids.
529	    fn iter(&self) -> impl Iterator<Item = (DedupId, &T)> {
530	        self.map.iter().map(|(hash, v)| (DedupId(self.kind, *hash), v))
531	    }
532	
533	    /// Returns true if the deduplicator is empty.
534	    fn is_empty(&self) -> bool {
535	        self.map.is_empty()
536	    }
537	}
538	
539	/// Identifies a `<def>`.
540	#[derive(Debug, Copy, Clone, Eq, PartialEq, Ord, PartialOrd, Hash)]
541	struct DedupId(char, u128);
542	
543	impl SvgDisplay for DedupId {
544	    fn fmt(&self, f: &mut impl SvgWrite) {
545	        let Self(kind, hash) = *self;
546	        f.push_char(kind);
547	
548	        let mut digits = [0; 32];
549	        for (i, byte) in hash.to_be_bytes().into_iter().enumerate() {
550	            digits[2 * i] = to_hex_digit((byte >> 4) & 0x0F);
551	            digits[2 * i + 1] = to_hex_digit(byte & 0x0F);
552	        }
553	
554	        // The digits are all valid ASCII hex characters.
555	        let str = std::str::from_utf8(&digits).unwrap();
556	        f.push_str(str.trim_start_matches('0'));
557	
558	        fn to_hex_digit(nibble: u8) -> u8 {
559	            match nibble {
560	                0..10 => b'0' + nibble,
561	                _ => b'A' + (nibble - 10),
562	            }
563	        }
564	    }
565	}
