186	/// Render a frame into the canvas.
187	fn render_frame(canvas: &mut sk::Pixmap, state: State, frame: &Frame) {
188	    for (pos, item) in frame.items() {
189	        match item {
190	            FrameItem::Group(group) => {
191	                render_group(canvas, state, *pos, group);
192	            }
193	            FrameItem::Text(text) => {
194	                text::render_text(canvas, state.pre_translate(*pos), text);
195	            }
196	            FrameItem::Shape(shape, _) => {
197	                shape::render_shape(canvas, state.pre_translate(*pos), shape);
198	            }
199	            FrameItem::Image(image, size, _) => {
200	                image::render_image(canvas, state.pre_translate(*pos), image, *size);
201	            }
202	            FrameItem::Link(_, _) => {}
203	            FrameItem::Tag(_) => {}
204	        }
205	    }
206	}
