55	pub fn svg_in_bundle(
56	    page: &Page,
57	    opts: &SvgOptions<Complete>,
58	    anchors: &[(Point, EcoString)],
59	    link_resolver: Tracked<LateLinkResolver>,
60	) -> String {
61	    let (size, ts) = page_bleed(page, opts);
62	
63	    let mut renderer = SVGRenderer::with_options(Some(link_resolver));
64	    let mut xml = XmlWriter::new(xml_options(opts.format.pretty.v));
65	    let mut svg = svg_header(&mut xml, size);
66	
67	    let state = State::new(size);
68	    renderer.render_page(&mut svg, &state, ts, page);
69	
70	    for (pos, id) in anchors {
