450	/// Write the default SVG header, including a `typst-doc` class, the
451	/// `viewBox` and `width` and `height` attributes.
452	fn svg_header(xml: &mut XmlWriter, size: Size) -> SvgElem<'_> {
453	    svg_header_with_custom_attrs(xml, size, |_| {})
454	}
455	
456	/// Write the SVG header with additional attributes and standard attributes.
457	fn svg_header_with_custom_attrs(
458	    xml: &mut XmlWriter,
459	    size: Size,
460	    write_custom_attrs: impl FnOnce(&mut SvgElem),
461	) -> SvgElem<'_> {
462	    // Clamp the size of SVGs to at least one pt. resvg and probably also
463	    // other SVG parsers don't handle SVGs with 0 sized dimensions.
464	    let size = size.max(Size::splat(Abs::pt(1.0)));
465	
466	    let mut svg = SvgElem::new(xml, "svg");
467	
468	    write_custom_attrs(&mut svg);
469	
470	    svg.attr_with("viewBox", |attr| {
471	        attr.push_nums([0.0, 0.0, size.x.to_pt(), size.y.to_pt()]);
472	    });
473	    svg.attr_with("width", |attr| {
474	        attr.push_num(size.x.to_pt());
475	        attr.push_str("pt");
476	    });
477	    svg.attr_with("height", |attr| {
478	        attr.push_num(size.y.to_pt());
479	        attr.push_str("pt");
480	    });
481	    svg.attr("xmlns", "http://www.w3.org/2000/svg");
482	    svg.attr("xmlns:xlink", "http://www.w3.org/1999/xlink");
483	    svg.attr("xmlns:h5", "http://www.w3.org/1999/xhtml");
484	
485	    svg
486	}
