21	            let h = size.y.to_f32();
22	            let rect = if w < 0.0 || h < 0.0 {
23	                // Skia doesn't normally allow for negative dimensions, but
24	                // Typst supports them, so we apply a transform if needed
25	                // Because this operation is expensive according to tiny-skia's
26	                // docs, we prefer to not apply it if not needed
27	                let transform = sk::Transform::from_scale(w.signum(), h.signum());
