43	/// Render an outline glyph into the canvas. This is the "normal" case.
44	fn render_outline_glyph(
45	    canvas: &mut sk::Pixmap,
46	    state: State,
47	    text: &TextItem,
48	    id: GlyphId,
49	) -> Option<()> {
50	    let ts = &state.transform;
51	    let ppem = text.size.to_f32() * ts.sy;
52	
53	    // Render a glyph directly as a path. This only happens when the fast glyph
54	    // rasterization can't be used due to very large text size or weird
55	    // scale/skewing transforms.
56	    if ppem > 100.0
57	        || ppem < 0.0
58	        || ts.kx != 0.0
59	        || ts.ky != 0.0
60	        || ts.sx != ts.sy
61	        || text.stroke.is_some()
62	    {
63	        let path = {
64	            let mut builder = WrappedPathBuilder(sk::PathBuilder::new());
65	            text.font.ttf().outline_glyph(id, &mut builder)?;
66	            builder.0.finish()?
67	        };
68	
69	        let scale = text.size.to_f32() / text.font.units_per_em() as f32;
70	
71	        let mut pixmap = None;
72	
73	        let rule = sk::FillRule::default();
74	
75	        // Flip vertically because font design coordinate
76	        // system is Y-up.
77	        let ts = ts.pre_scale(scale, -scale);
78	        let state_ts = state.pre_concat(sk::Transform::from_scale(scale, -scale));
79	        let paint =
80	            paint::to_sk_paint(&text.fill, state_ts, true, &mut pixmap, None, false);
81	        canvas.fill_path(&path, &paint, rule, ts, state.mask);
82	
83	        if let Some(FixedStroke { paint, thickness, cap, join, dash, miter_limit }) =
84	            &text.stroke
85	            && thickness.to_f32() > 0.0
86	        {
87	            let dash = dash.as_ref().and_then(shape::to_sk_dash_pattern);
88	
89	            let paint =
90	                paint::to_sk_paint(paint, state_ts, true, &mut pixmap, None, false);
91	            let stroke = sk::Stroke {
92	                width: thickness.to_f32() / scale, // When we scale the path, we need to scale the stroke width, too.
93	                line_cap: shape::to_sk_line_cap(*cap),
94	                line_join: shape::to_sk_line_join(*join),
95	                dash,
96	                miter_limit: miter_limit.get() as f32,
97	            };
98	
99	            canvas.stroke_path(&path, &paint, &stroke, ts, state.mask);
100	        }
101	        return Some(());
102	    }
103	
104	    // Rasterize the glyph with `pixglyph`.
105	    #[comemo::memoize]
106	    fn rasterize(
107	        font: &FontInstance,
108	        id: GlyphId,
109	        x: u32,
110	        y: u32,
111	        size: u32,
112	    ) -> Option<Arc<Bitmap>> {
113	        let glyph = pixglyph::Glyph::load(font.ttf(), id)?;
114	        Some(Arc::new(glyph.rasterize(
115	            f32::from_bits(x),
116	            f32::from_bits(y),
117	            f32::from_bits(size),
118	        )))
119	    }
120	
121	    // Try to retrieve a prepared glyph or prepare it from scratch if it
122	    // doesn't exist, yet.
123	    let bitmap =
124	        rasterize(&text.font, id, ts.tx.to_bits(), ts.ty.to_bits(), ppem.to_bits())?;
125	    match &text.fill {
126	        Paint::Gradient(gradient) => {
127	            let sampler = GradientSampler::new(gradient, &state, Size::zero(), true);
128	            write_bitmap(canvas, &bitmap, &state, sampler)?;
129	        }
130	        Paint::Solid(color) => {
131	            write_bitmap(
132	                canvas,
133	                &bitmap,
134	                &state,
135	                paint::to_sk_color_u8(color.to_process()).premultiply(),
136	            )?;
137	        }
138	        Paint::Tiling(tiling) => {
139	            let pixmap = paint::render_tiling_frame(&state, tiling);
140	            let sampler = TilingSampler::new(tiling, &pixmap, &state, true);
141	            write_bitmap(canvas, &bitmap, &state, sampler)?;
142	        }
143	    }
144	
145	    Some(())
146	}
147	
148	fn write_bitmap<S: PaintSampler>(
149	    canvas: &mut sk::Pixmap,
150	    bitmap: &Bitmap,
151	    state: &State,
152	    sampler: S,
153	) -> Option<()> {
154	    // If we have a clip mask we first render to a pixmap that we then blend
155	    // with our canvas
156	    if state.mask.is_some() {
157	        let cw = canvas.width() as i32;
158	        let ch = canvas.height() as i32;
159	        let mw = bitmap.width;
160	        let mh = bitmap.height;
161	
162	        let left = bitmap.left;
163	        let top = bitmap.top;
164	
165	        // Pad the pixmap with 1 pixel in each dimension so that we do
166	        // not get any problem with floating point errors along their border
167	        let mut pixmap = sk::Pixmap::new(mw + 2, mh + 2)?;
168	        let pixels = bytemuck::cast_slice_mut::<u8, u32>(pixmap.data_mut());
169	        for x in 0..mw {
170	            for y in 0..mh {
171	                let alpha = bitmap.coverage[(y * mw + x) as usize];
172	
173	                // To sample at the correct position, we need to convert each
174	                // pixel's position in the bitmap (x and y) to its final
175	                // expected position in the canvas. Due to padding, this
176	                // pixel's position in the pixmap will be (x + 1, y + 1).
177	                // Then, when drawing the pixmap to the canvas, we place its
178	                // top-left corner at position (left - 1, top - 1). Therefore,
179	                // the final position of this pixel in the canvas is given by
180	                // (left - 1 + x + 1, top - 1 + y + 1) = (left + x, top + y).
181	                let sample_pos = (
182	                    (left + x as i32).clamp(0, cw) as u32,
183	                    (top + y as i32).clamp(0, ch) as u32,
184	                );
185	                let color = sampler.sample(sample_pos);
186	                let color = bytemuck::cast(color);
187	
188	                let applied = alpha_mul(color, alpha as u32);
189	                pixels[((y + 1) * (mw + 2) + (x + 1)) as usize] = applied;
190	            }
191	        }
192	
193	        canvas.draw_pixmap(
194	            left - 1,
195	            top - 1,
196	            pixmap.as_ref(),
197	            &sk::PixmapPaint::default(),
198	            sk::Transform::identity(),
199	            state.mask,
200	        );
201	    } else {
202	        let cw = canvas.width() as i32;
203	        let ch = canvas.height() as i32;
204	        let mw = bitmap.width as i32;
205	        let mh = bitmap.height as i32;
206	
207	        // Determine the pixel bounding box that we actually need to draw.
208	        let left = bitmap.left;
209	        let right = left + mw;
210	        let top = bitmap.top;
211	        let bottom = top + mh;
212	
213	        // Blend the glyph bitmap with the existing pixels on the canvas.
214	        let pixels = bytemuck::cast_slice_mut::<u8, u32>(canvas.data_mut());
215	        for x in left.clamp(0, cw)..right.clamp(0, cw) {
216	            for y in top.clamp(0, ch)..bottom.clamp(0, ch) {
217	                let ai = ((y - top) * mw + (x - left)) as usize;
218	                let cov = bitmap.coverage[ai];
219	                if cov == 0 {
220	                    continue;
221	                }
222	
223	                let color = sampler.sample((x as u32, y as u32));
224	                let color = bytemuck::cast(color);
225	                let pi = (y * cw + x) as usize;
226	                // Fast path if color is opaque.
227	                if cov == u8::MAX && color & 0xFF == 0xFF {
228	                    pixels[pi] = color;
229	                    continue;
230	                }
231	
232	                let applied = alpha_mul(color, cov as u32);
233	                pixels[pi] = blend_src_over(applied, pixels[pi]);
234	            }
235	        }
236	    }
237	
238	    Some(())
239	}
