10	/// Render a geometrical shape into the canvas.
11	pub fn render_shape(canvas: &mut sk::Pixmap, state: State, shape: &Shape) -> Option<()> {
12	    let ts = state.transform;
13	    let path = match &shape.geometry {
14	        Geometry::Line(target) => {
15	            let mut builder = sk::PathBuilder::new();
16	            builder.line_to(target.x.to_f32(), target.y.to_f32());
17	            builder.finish()?
18	        }
19	        Geometry::Rect(size) => {
20	            let w = size.x.to_f32();
21	            let h = size.y.to_f32();
22	            let rect = if w < 0.0 || h < 0.0 {
23	                // Skia doesn't normally allow for negative dimensions, but
24	                // Typst supports them, so we apply a transform if needed
25	                // Because this operation is expensive according to tiny-skia's
26	                // docs, we prefer to not apply it if not needed
27	                let transform = sk::Transform::from_scale(w.signum(), h.signum());
28	                let rect = sk::Rect::from_xywh(0.0, 0.0, w.abs(), h.abs())?;
29	                rect.transform(transform)?
30	            } else {
31	                sk::Rect::from_xywh(0.0, 0.0, w, h)?
32	            };
33	
34	            sk::PathBuilder::from_rect(rect)
35	        }
36	        Geometry::Curve(curve) => convert_curve(curve)?,
37	    };
38	
39	    if let Some(fill) = &shape.fill {
40	        let mut pixmap = None;
41	        let mut paint: sk::Paint =
42	            paint::to_sk_paint(fill, state, false, &mut pixmap, Some(shape), false);
43	
44	        if matches!(shape.geometry, Geometry::Rect(_)) {
45	            paint.anti_alias = false;
46	        }
47	
48	        let rule = match shape.fill_rule {
49	            FillRule::NonZero => sk::FillRule::Winding,
50	            FillRule::EvenOdd => sk::FillRule::EvenOdd,
51	        };
52	        canvas.fill_path(&path, &paint, rule, ts, state.mask);
53	    }
54	
55	    if let Some(FixedStroke { paint, thickness, cap, join, dash, miter_limit }) =
56	        &shape.stroke
57	    {
58	        let width = thickness.to_f32();
59	
60	        // Don't draw zero-pt stroke.
61	        if width > 0.0 {
62	            let dash = dash.as_ref().and_then(to_sk_dash_pattern);
63	            let mut pixmap = None;
64	            let paint = paint::to_sk_paint(
65	                paint,
66	                state,
67	                false,
68	                &mut pixmap,
69	                Some(shape),
70	                matches!(paint, Paint::Gradient(_)),
71	            );
72	            let stroke = sk::Stroke {
73	                width,
74	                line_cap: to_sk_line_cap(*cap),
75	                line_join: to_sk_line_join(*join),
76	                dash,
77	                miter_limit: miter_limit.get() as f32,
78	            };
79	            canvas.stroke_path(&path, &paint, &stroke, ts, state.mask);
80	        }
81	    }
82	
83	    Some(())
84	}
