115	pub fn to_sk_line_cap(cap: LineCap) -> sk::LineCap {
116	    match cap {
117	        LineCap::Butt => sk::LineCap::Butt,
118	        LineCap::Round => sk::LineCap::Round,
119	        LineCap::Square => sk::LineCap::Square,
120	    }
121	}
122	
123	pub fn to_sk_line_join(join: LineJoin) -> sk::LineJoin {
124	    match join {
125	        LineJoin::Miter => sk::LineJoin::Miter,
126	        LineJoin::Round => sk::LineJoin::Round,
127	        LineJoin::Bevel => sk::LineJoin::Bevel,
128	    }
129	}
130	
131	pub fn to_sk_dash_pattern(dash: &DashPattern<Abs, Abs>) -> Option<sk::StrokeDash> {
132	    // tiny-skia only allows dash patterns with an even number of elements,
133	    // while pdf allows any number.
134	    let pattern_len = dash.array.len();
135	    let len = if pattern_len % 2 == 1 { 2 * pattern_len } else { pattern_len };
136	    let dash_array = dash.array.iter().map(|l| l.to_f32()).cycle().take(len).collect();
137	    sk::StrokeDash::new(dash_array, dash.phase.to_f32())
138	}
