17	/// Render a raster or SVG image into the canvas.
18	pub fn render_image(
19	    canvas: &mut sk::Pixmap,
20	    state: State,
21	    image: &Image,
22	    size: Size,
23	) -> Option<()> {
24	    let ts = state.transform;
25	    let view_width = size.x.to_f32();
26	    let view_height = size.y.to_f32();
27	
28	    // For better-looking output, resize `image` to its final size before
29	    // painting it to `canvas`. For the math, see:
30	    // https://github.com/typst/typst/issues/1404#issuecomment-1598374652
31	    let theta = libm::atan2f(-ts.kx, ts.sx);
32	
33	    // To avoid division by 0, choose the one of { sin, cos } that is
34	    // further from 0.
35	    let prefer_sin = libm::sinf(theta).abs() > std::f32::consts::FRAC_1_SQRT_2;
36	    let scale_x = f32::abs(if prefer_sin {
37	        ts.kx / libm::sinf(theta)
38	    } else {
39	        ts.sx / libm::cosf(theta)
40	    });
41	
42	    let aspect = (image.width() as f32) / (image.height() as f32);
43	    let w = (scale_x * view_width.max(aspect * view_height)).ceil() as u32;
44	    let h = ((w as f32) / aspect).ceil() as u32;
45	
46	    let pixmap = build_texture(image, w, h)?;
47	    let paint_scale_x = view_width / pixmap.width() as f32;
48	    let paint_scale_y = view_height / pixmap.height() as f32;
49	
50	    let paint = sk::Paint {
51	        shader: sk::Pattern::new(
52	            (*pixmap).as_ref(),
53	            sk::SpreadMode::Pad,
54	            sk::FilterQuality::Nearest,
55	            1.0,
56	            sk::Transform::from_scale(paint_scale_x, paint_scale_y),
57	        ),
58	        ..Default::default()
59	    };
60	
61	    let rect = sk::Rect::from_xywh(0.0, 0.0, view_width, view_height)?;
62	    canvas.fill_rect(rect, &paint, ts, state.mask);
63	
64	    Some(())
65	}
66	
67	/// Prepare a texture for an image at a scaled size.
68	#[comemo::memoize]
69	fn build_texture(image: &Image, w: u32, h: u32) -> Option<Arc<sk::Pixmap>> {
70	    let texture = match image.kind() {
71	        ImageKind::Raster(raster) => {
72	            let mut texture = sk::Pixmap::new(w, h)?;
73	            let w = texture.width();
74	            let h = texture.height();
75	
76	            let buf;
77	            let dynamic = raster.dynamic();
78	            let resized = if (w, h) == (dynamic.width(), dynamic.height()) {
79	                // Small optimization to not allocate in case image is not resized.
80	                dynamic
81	            } else {
82	                let upscale = w > dynamic.width();
83	                let filter = match image.scaling() {
84	                    Smart::Custom(ImageScaling::Pixelated) => FilterType::Nearest,
85	                    _ if upscale => FilterType::CatmullRom,
86	                    _ => FilterType::Lanczos3, // downscale
87	                };
88	                buf = dynamic.resize_exact(w, h, filter);
89	                &buf
90	            };
91	
92	            for ((_, _, src), dest) in resized.pixels().zip(texture.pixels_mut()) {
93	                let Rgba([r, g, b, a]) = src;
94	                *dest = sk::ColorU8::from_rgba(r, g, b, a).premultiply();
95	            }
96	
97	            texture
98	        }
99	        ImageKind::Svg(svg) => {
100	            let mut texture = sk::Pixmap::new(w, h)?;
101	            let tree = svg.tree();
102	            let ts = tiny_skia::Transform::from_scale(
103	                w as f32 / tree.size().width(),
104	                h as f32 / tree.size().height(),
105	            );
106	            resvg::render(tree, ts, &mut texture.as_mut());
107	            texture
108	        }
109	        ImageKind::Pdf(pdf) => build_pdf_texture(pdf, w, h)?,
110	    };
111	
112	    Some(Arc::new(texture))
113	}
114	
115	// Keep this in sync with `typst-svg`!
116	fn build_pdf_texture(pdf: &PdfImage, w: u32, h: u32) -> Option<sk::Pixmap> {
117	    let select_standard_font = move |font: StandardFont| -> Option<(FontData, u32)> {
118	        let bytes = match font {
119	            StandardFont::Helvetica => typst_assets::pdf::SANS,
120	            StandardFont::HelveticaBold => typst_assets::pdf::SANS_BOLD,
121	            StandardFont::HelveticaOblique => typst_assets::pdf::SANS_ITALIC,
122	            StandardFont::HelveticaBoldOblique => typst_assets::pdf::SANS_BOLD_ITALIC,
123	            StandardFont::Courier => typst_assets::pdf::FIXED,
124	            StandardFont::CourierBold => typst_assets::pdf::FIXED_BOLD,
125	            StandardFont::CourierOblique => typst_assets::pdf::FIXED_ITALIC,
126	            StandardFont::CourierBoldOblique => typst_assets::pdf::FIXED_BOLD_ITALIC,
127	            StandardFont::TimesRoman => typst_assets::pdf::SERIF,
128	            StandardFont::TimesBold => typst_assets::pdf::SERIF_BOLD,
129	            StandardFont::TimesItalic => typst_assets::pdf::SERIF_ITALIC,
130	            StandardFont::TimesBoldItalic => typst_assets::pdf::SERIF_BOLD_ITALIC,
131	            StandardFont::ZapfDingBats => typst_assets::pdf::DING_BATS,
132	            StandardFont::Symbol => typst_assets::pdf::SYMBOL,
133	        };
134	        Some((Arc::new(bytes), 0))
135	    };
136	
137	    let interpreter_settings = InterpreterSettings {
138	        font_resolver: Arc::new(move |query| match query {
139	            FontQuery::Standard(s) => select_standard_font(*s),
140	            FontQuery::Fallback(f) => select_standard_font(f.pick_standard_font()),
141	        }),
142	        // Fairly niche and enabling hayro's embedded cmap would add a
143	        // considerable amount of data.
144	        cmap_resolver: Arc::new(|_| None),
145	        warning_sink: Arc::new(|_| {}),
146	        // We want to render like it prints, so no annotations.
147	        render_annotations: false,
148	    };
149	
150	    let render_settings = RenderSettings {
151	        x_scale: w as f32 / pdf.width(),
152	        y_scale: h as f32 / pdf.height(),
153	        width: Some(w as u16),
