1	use ecow::EcoString;
2	use ttf_parser::GlyphId;
3	use typst_library::layout::{Abs, Ratio, Size, Transform};
4	use typst_library::text::TextItem;
5	use typst_library::text::color::{
6	    GlyphFrame, GlyphFrameItem, glyph_frame, should_outline,
7	};
8	use typst_library::visualize::{FillRule, Paint, RelativeTo};
9	
10	use crate::path::SvgPathBuilder;
11	use crate::write::{SvgElem, SvgIdRef, SvgTransform};
12	use crate::{DedupId, SVGRenderer, State};
13	
14	/// Represents a glyph to be rendered.
15	#[derive(Clone)]
16	pub enum RenderedGlyph {
17	    /// A frame that contains an image glpyh.
18	    Frame(GlyphFrame),
19	    /// A path is a sequence of drawing commands.
20	    ///
21	    /// It is in the format of `M x y L x y C x1 y1 x2 y2 x y Z`.
22	    Path(EcoString),
23	}
24	
25	impl SVGRenderer<'_> {
26	    /// Render a text item. The text is rendered as a group of glyphs. We will
27	    /// try to render the text as SVG first, then bitmap, then outline. If none
28	    /// of them works, we will skip the text.
29	    pub(super) fn render_text(
30	        &mut self,
31	        svg: &mut SvgElem,
32	        state: &State,
33	        text: &TextItem,
34	    ) {
35	        let svg = &mut svg.elem("g");
36	
37	        // Flip the transform since fonts use a Y-Up coordinate system.
38	        let state = state.pre_concat(Transform::scale(Ratio::one(), -Ratio::one()));
39	        svg.attr("transform", SvgTransform(state.transform));
40	
41	        let mut x = Abs::pt(0.0);
42	        let mut y = Abs::pt(0.0);
43	        for glyph in &text.glyphs {
44	            let id = GlyphId(glyph.id);
45	            let x_offset = x + glyph.x_offset.at(text.size);
46	            let y_offset = y + glyph.y_offset.at(text.size);
47	
48	            self.render_glyph(svg, &state, text, id, x_offset, y_offset);
49	
50	            x += glyph.x_advance.at(text.size);
51	            y += glyph.y_advance.at(text.size);
52	        }
53	    }
54	
55	    fn render_glyph(
56	        &mut self,
57	        svg: &mut SvgElem,
58	        state: &State,
59	        text: &TextItem,
60	        glyph_id: GlyphId,
61	        x_offset: Abs,
62	        y_offset: Abs,
63	    ) {
64	        if should_outline(&text.font, glyph_id) {
65	            // Pre-scale outlined glyphs, so strokes and fill patterns don't
66	            // need to consider text size glyph scaling.
67	            let scale = Ratio::new(text.size.to_pt() / text.font.units_per_em());
68	            let key = (&text.font, glyph_id, scale);
69	            let (id, path) = self.glyphs.insert_with_val(key, || {
70	                let mut builder = SvgPathBuilder::with_scale(scale);
71	                text.font.ttf().outline_glyph(glyph_id, &mut builder)?;
72	                Some(RenderedGlyph::Path(builder.finish()))
73	            });
74	
75	            if path.is_some() {
76	                self.render_path_glyph(
77	                    svg, state, text, glyph_id, x_offset, y_offset, id,
78	                );
79	            }
80	        } else {
81	            // Image glyphs apply a `scale` at use site, since colr, svg-, and
82	            // bitmap glyph images are usually quite large, and having one glyph
83	            // per text size is a bit of a waste.
84	            let key = (&text.font, glyph_id);
85	            let (id, frame) = self.glyphs.insert_with_val(key, || {
86	                let frame = glyph_frame(&text.font, glyph_id.0)?;
87	                Some(RenderedGlyph::Frame(frame))
88	            });
89	
90	            if frame.is_some() {
91	                self.render_image_glyph(svg, x_offset, y_offset, text, id);
92	            }
93	        }
94	    }
95	
96	    /// Write a reference to an image glyph that is stored in font units.
97	    fn render_image_glyph(
98	        &mut self,
99	        svg: &mut SvgElem,
100	        x_offset: Abs,
101	        y_offset: Abs,
102	        text: &TextItem,
103	        id: DedupId,
104	    ) {
105	        let scale = Ratio::new(text.size.to_pt() / text.font.units_per_em());
106	        // Flip the transform again, since images are drawn Y-Down.
107	        let ts = Transform::translate(x_offset, y_offset)
108	            .pre_concat(Transform::scale(scale, -scale));
109	
110	        svg.elem("use")
111	            .attr("xlink:href", SvgIdRef(id))
112	            .attr("transform", SvgTransform(ts));
113	    }
114	
115	    /// Render a pre-scaled path glyph defined by an outline.
116	    #[expect(clippy::too_many_arguments)]
117	    fn render_path_glyph(
118	        &mut self,
119	        svg: &mut SvgElem,
120	        state: &State,
121	        text: &TextItem,
122	        glyph_id: GlyphId,
123	        x_offset: Abs,
124	        y_offset: Abs,
125	        id: DedupId,
126	    ) {
127	        // Apply the transform here, because the state transform is used to draw
128	        // strokes and fills with gradients and tilings.
129	        let state = state.pre_concat(Transform::translate(x_offset, y_offset));
130	
131	        let Some(glyph_size) = text.font.ttf().glyph_bounding_box(glyph_id) else {
132	            // This shouldn't happen, because the glyph has been successfully
133	            // outlined to create the path.
134	            return;
135	        };
136	
137	        let aspect_ratio = Size::new(
138	            Abs::pt(glyph_size.width() as f64),
139	            Abs::pt(glyph_size.height() as f64),
140	        )
141	        .aspect_ratio();
142	
143	        let mut use_ = svg.elem("use");
144	        use_.attr("xlink:href", SvgIdRef(id))
145	            .attr("x", x_offset.to_pt())
146	            .attr("y", y_offset.to_pt());
147	
148	        self.write_fill(
149	            &mut use_,
150	            &text.fill,
151	            FillRule::default(),
152	            aspect_ratio,
153	            self.text_paint_transform(&state, &text.fill),
154	        );
155	        if let Some(stroke) = &text.stroke {
156	            self.write_stroke(
157	                &mut use_,
158	                stroke,
159	                aspect_ratio,
160	                self.text_paint_transform(&state, &stroke.paint),
161	            );
162	        }
163	    }
164	
165	    fn text_paint_transform(&self, state: &State, paint: &Paint) -> Transform {
166	        match paint {
167	            Paint::Solid(_) => Transform::identity(),
168	            Paint::Gradient(gradient) => match gradient.unwrap_relative(true) {
169	                RelativeTo::Self_ => Transform::identity(),
170	                RelativeTo::Parent => Transform::scale(
171	                    Ratio::new(state.size.x.to_pt()),
172	                    Ratio::new(state.size.y.to_pt()),
173	                )
174	                .post_concat(state.transform.invert().unwrap()),
175	            },
176	            Paint::Tiling(tiling) => match tiling.unwrap_relative(true) {
177	                RelativeTo::Self_ => Transform::identity(),
178	                RelativeTo::Parent => state.transform.invert().unwrap(),
179	            },
180	        }
181	    }
182	
183	    /// Build the glyph definitions.
184	    pub(super) fn write_glyph_defs(&mut self, svg: &mut SvgElem) {
185	        if self.glyphs.iter().all(|(_, g)| g.is_none()) {
186	            return;
187	        }
188	
189	        let mut defs = svg.elem("defs");
190	        let glyphs = std::mem::take(&mut self.glyphs);
191	        for (id, glyph) in glyphs.iter() {
192	            let Some(glyph) = glyph else { continue };
193	
194	            let mut symbol = defs.elem("symbol");
195	            symbol.attr("id", id);
196	            symbol.attr("overflow", "visible");
197	
198	            match glyph {
199	                RenderedGlyph::Frame(frame) => {
200	                    let state = State::new(frame.size()).pre_translate(frame.item.pos());
201	                    match &frame.item {
202	                        GlyphFrameItem::Tofu(_, shape) => {
203	                            self.render_shape(&mut symbol, &state, shape);
204	                        }
205	                        GlyphFrameItem::Image(_, image, size) => {
206	                            self.render_image(&mut symbol, &state, image, size);
207	                        }
208	                    }
209	                }
210	                RenderedGlyph::Path(path) => {
211	                    symbol.elem("path").attr("d", path);
212	                }
213	            }
214	        }
215	
216	        // The glyphs have been taken above, there shouldn't be any new glyphs
217	        // produced from writing the glyph definitions.
218	        assert!(self.glyphs.is_empty());
219	    }
220	}
