11	impl SVGRenderer<'_> {
12	    /// Render a shape element.
13	    pub(super) fn render_shape(
14	        &mut self,
15	        svg: &mut SvgElem,
16	        state: &State,
17	        shape: &Shape,
18	    ) {
19	        let svg = &mut svg.elem("path");
