601	fn render(document: &PagedDocument, pixel_per_pt: f32) -> sk::Pixmap {
602	    for page in document.pages() {
603	        let limit = Abs::cm(100.0);
604	        if page.frame.width() > limit || page.frame.height() > limit {
605	            panic!("overlarge frame: {:?}", page.frame.size());
606	        }
607	    }
608	
609	    let gap = Abs::pt(1.0);
610	    let ppi = pixel_per_pt * 72.0;
611	    let opts = typst_render::RenderOptions {
612	        format: PngFormatOptions { ppi: Some(Scalar::new(ppi as f64)) },
613	        render_bleed: false,
614	    };
615	    let mut pixmap =
616	        typst_render::render_merged(document, &opts, gap, Some(Color::BLACK));
617	
618	    let gap = (pixel_per_pt * gap.to_pt() as f32).round();
619	
620	    let mut y = 0.0;
621	    for page in document.pages() {
622	        let ts =
623	            sk::Transform::from_scale(pixel_per_pt, pixel_per_pt).post_translate(0.0, y);
624	        render_links(&mut pixmap, ts, &page.frame);
625	        y += (pixel_per_pt * page.frame.height().to_pt() as f32).round().max(1.0) + gap;
626	    }
627	
628	    pixmap
629	}
