527	/// Exports the document's pages as separate images, each exported with a
528	/// format-specific `export_image_page` function.
529	fn export_image_pages<F>(
530	    config: &CompileConfig,
531	    document: &PagedDocument,
532	    export_image_page: F,
533	) -> StrResult<Vec<Output>>
534	where
535	    F: Fn(&Page, &Output) -> StrResult<()>,
536	    F: Send + Sync,
537	{
538	    // Determine whether we have indexable templates in output
539	    let can_handle_multiple = match config.output {
540	        Output::Stdout => false,
541	        Output::Path(ref output) => {
542	            output_template::has_indexable_template(output.to_str().unwrap_or_default())
543	        }
544	    };
545	
546	    let exported_pages = document
547	        .pages()
548	        .iter()
549	        .enumerate()
550	        .filter(|(i, _)| {
551	            config.pages.as_ref().is_none_or(|exported_page_ranges| {
552	                exported_page_ranges.includes_page_index(*i)
553	            })
554	        })
555	        .collect::<Vec<_>>();
556	
557	    if !can_handle_multiple && exported_pages.len() > 1 {
558	        let err = match config.output {
559	            Output::Stdout => "to stdout",
560	            Output::Path(_) => {
561	                "without a page number template ({p}, {0p}) in the output path"
562	            }
563	        };
564	        bail!("cannot export multiple images {err}");
565	    }
566	
567	    // The results are collected in a `Vec<()>` which does not allocate.
568	    exported_pages
569	        .par_iter()
570	        .map(|(i, page)| {
571	            // Use output with converted path.
572	            let output = match &config.output {
573	                Output::Path(path) => {
574	                    let storage;
575	                    let path = if can_handle_multiple {
576	                        storage = output_template::format(
577	                            path.to_str().unwrap_or_default(),
578	                            i + 1,
579	                            document.pages().len(),
580	                        );
581	                        Path::new(&storage)
582	                    } else {
583	                        path
584	                    };
585	
586	                    // If we are not watching, don't use the cache.
587	                    // If the frame is in the cache, skip it.
588	                    // If the file does not exist, always create it.
589	                    if config.watching
590	                        && config.export_cache.is_cached(*i, page)
591	                        && path.exists()
592	                    {
593	                        return Ok(Output::Path(path.to_owned()));
594	                    }
595	
596	                    Output::Path(path.to_owned())
597	                }
598	                Output::Stdout => Output::Stdout,
599	            };

