304	            StandardFont::CourierBoldOblique => typst_assets::pdf::FIXED_BOLD_ITALIC,
305	            StandardFont::TimesRoman => typst_assets::pdf::SERIF,
306	            StandardFont::TimesBold => typst_assets::pdf::SERIF_BOLD,
307	            StandardFont::TimesItalic => typst_assets::pdf::SERIF_ITALIC,
