use std::sync::Arc;

use tiny_skia as sk;
use typst_library::layout::{Abs, Axes, Point, Ratio, Size};
use typst_library::visualize::{
    Geometry, Gradient, Paint, ProcessColor, RelativeTo, Shape, Tiling,
};

use crate::{AbsExt, State, to_sk_transform};

/// Trait for sampling of a paint, used as a generic
/// abstraction over solid colors and gradients.
pub trait PaintSampler: Copy {
    /// Sample the color at the `pos` in the pixmap.
    fn sample(self, pos: (u32, u32)) -> sk::PremultipliedColorU8;
}

impl PaintSampler for sk::PremultipliedColorU8 {
    fn sample(self, _: (u32, u32)) -> sk::PremultipliedColorU8 {
        self
    }
}

/// State used when sampling colors for text.
///
/// It caches the inverse transform to the parent, so that we can
/// reuse it instead of recomputing it for each pixel.
#[derive(Copy, Clone)]
pub struct GradientSampler<'a> {
    gradient: &'a Gradient,
    container_size: Size,
    transform_to_parent: sk::Transform,
}

impl<'a> GradientSampler<'a> {
    pub fn new(
        gradient: &'a Gradient,
        state: &State,
        item_size: Size,
        on_text: bool,
    ) -> Self {
        let relative = gradient.unwrap_relative(on_text);
        let container_size = match relative {
            RelativeTo::Self_ => item_size,
            RelativeTo::Parent => state.size,
        };

        let fill_transform = match relative {
            RelativeTo::Self_ => sk::Transform::identity(),
            RelativeTo::Parent => state.container_transform.invert().unwrap(),
        };

        Self {
            gradient,
            container_size,
            transform_to_parent: fill_transform,
        }
    }
}

impl PaintSampler for GradientSampler<'_> {
    /// Samples a single point in a glyph.
    fn sample(self, (x, y): (u32, u32)) -> sk::PremultipliedColorU8 {
        // Compute the point in the gradient's coordinate space.
        let mut point = sk::Point { x: x as f32, y: y as f32 };
        self.transform_to_parent.map_point(&mut point);

        // Sample the gradient
        to_sk_color_u8(
            self.gradient
                .sample_at(
                    (point.x, point.y),
                    (self.container_size.x.to_f32(), self.container_size.y.to_f32()),
                )
                .to_process(),
        )
        .premultiply()
    }
}

/// State used when sampling tilings for text.
///
/// It caches the inverse transform to the parent, so that we can
/// reuse it instead of recomputing it for each pixel.
#[derive(Copy, Clone)]
pub struct TilingSampler<'a> {
    size: Size,
    transform_to_parent: sk::Transform,
    pixmap: &'a sk::Pixmap,
    pixel_per_pt: f32,
}

impl<'a> TilingSampler<'a> {
    pub fn new(
        tilings: &'a Tiling,
        pixmap: &'a sk::Pixmap,
        state: &State,
        on_text: bool,
    ) -> Self {
        let relative = tilings.unwrap_relative(on_text);
        let fill_transform = match relative {
            RelativeTo::Self_ => sk::Transform::identity(),
            RelativeTo::Parent => state.container_transform.invert().unwrap(),
        };
        let pattern_transform = to_sk_transform(&tilings.transform());

        Self {
            pixmap,
            size: (tilings.size() + tilings.spacing()) * state.pixel_per_pt as f64,
            transform_to_parent: fill_transform
                .post_concat(pattern_transform.invert().unwrap_or_default()),
            pixel_per_pt: state.pixel_per_pt,
        }
    }
}

impl PaintSampler for TilingSampler<'_> {
    /// Samples a single point in a glyph.
    fn sample(self, (x, y): (u32, u32)) -> sk::PremultipliedColorU8 {
        // Compute the point in the tilings's coordinate space.

use typst_library::diag::{SourceResult, bail};
use typst_library::engine::Engine;
use typst_library::format::{Complete, Fields, Format, FormatElement, Partial, Populate};
use typst_library::foundations::{Args, Construct, Content, StyleChain};
use typst_macros::elem;
use typst_syntax::Spanned;
use typst_utils::Scalar;

/// The format element for registering the PNG format.
pub const FORMAT: Format = Format::new::<PngFormat>();

/// Typst's PNG export format.
///
/// Instead of creating a PDF, Typst can also directly render pages to PNG
/// raster graphics. PNGs are losslessly compressed images that can contain one
/// page at a time. When exporting a multi-page document, Typst will emit
/// multiple PNGs. PNGs are a good choice when you want to use Typst's output in
/// an image editing software or when you can use none of Typst's other export
/// formats.
///
/// In contrast to Typst's other export formats, PNGs are bound to a specific
/// resolution. When exporting to PNG, you can configure the resolution as
/// pixels per inch (PPI). If the medium you view the PNG on has a finer
/// resolution than the PNG you exported, you will notice a loss of quality.
/// Typst calculates the resolution of your PNGs based on each page's physical
/// dimensions and the PPI. If you need guidance for choosing a PPI value,
/// consider the following:
///
/// - A value of 300 or 600 is typical for desktop printing.
/// - Professional prints of detailed graphics can go up to 1200 PPI.
/// - If your document is only viewed at a distance, e.g. a poster, you may
///   choose a smaller value than 300.
/// - If your document is viewed on screens, a typical PPI value for a
///   smartphone is 400-500.
///
/// Because PNGs only contain a pixel raster, the text within cannot be
/// extracted automatically (without OCR), for example by copy/paste or a screen
/// reader. If you need the text to be accessible, export a PDF or HTML file
/// instead.
///
/// PNGs can have transparent backgrounds. By default, Typst will output a PNG
/// with an opaque white background. You can make the background transparent
/// using `[#set page(fill: none)]`. Learn more on the @page.fill[`page`
/// function's reference page].
///
/// = Exporting as PNG <exporting-as-png>
/// == Command Line <command-line>
/// Pass `--format png` to the `compile` or `watch` subcommand or provide an
/// output file name that ends with `.png`.
///
/// If your document has more than one page, Typst will create multiple image
/// files. The output file name must then be a template string containing at
/// least one of
/// - `[{p}]`, which will be replaced by the page number
/// - `[{0p}]`, which will be replaced by the zero-padded page number (so that
///   all numbers have the same length)
/// - `[{t}]`, which will be replaced by the total number of pages
///
/// When exporting to PNG, you have the following configuration options:
///
/// - Which resolution to render at by specifying `--ppi` followed by a number
///   of pixels per inch. The default is `144`.
///
/// - Which pages to export by specifying `--pages` followed by a
///   comma-separated list of numbers or dash-separated number ranges. Ranges
///   can be half-open. Example: `2,3,7-9,11-`.
///
/// == Web App <web-app>
/// Click "File" > "Export as" > "PNG" or click the downwards-facing arrow next
/// to the quick download button and select "Export as PNG". When exporting to
/// PNG, you have the following configuration options:
///
/// - The resolution at which the pages should be rendered, as a number of
///   pixels per inch. The default is `144`.
///
/// - Which pages to export. Valid options are "All pages", "Current page", and
///   "Custom ranges". Custom ranges are a comma-separated list of numbers or
///   dash-separated number ranges. Ranges can be half-open. Example:
///   `2,3,7-9,11-`.
#[elem(name = "png", title = "PNG", since = "unreleased", Construct)]
pub struct PngFormat {
    /// The PPI (pixels per inch) to use for PNG export.
    #[default(Scalar::new(144.0))]
    pub ppi: Scalar,
}

impl FormatElement for PngFormat {
    type Options = PngFormatOptions;
}

impl Construct for PngFormat {
    fn construct(_: &mut Engine, args: &mut Args) -> SourceResult<Content> {
        bail!(args.span, "cannot be constructed manually")
    }
}

/// Document settings for PNG export.
#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
pub struct PngFormatOptions<F: Fields = Complete> {
    /// The PPI (pixels per inch) to render at when exporting a PNG.
    pub ppi: F::Value<PngFormat, { PngFormat::ppi.index() }>,
}

impl Populate for PngFormatOptions {
    fn populate(&mut self, styles: Spanned<StyleChain>) {
        // VOLATILE: This must be updated when adding more fields.
        self.ppi.populate(styles);
    }
}

impl PngFormatOptions<Partial> {
    /// Resolves the [`Partial`] options to [`Complete`] ones, given defaults.
    pub fn resolve(&self, default: &PngFormatOptions) -> PngFormatOptions {
        PngFormatOptions { ppi: Partial::resolve(self.ppi, default.ppi) }
    }
}

