//! Finished documents.

use std::fmt::{self, Debug, Formatter};
use std::sync::Arc;

use typst_syntax::Span;
use typst_utils::{LazyHash, Numeric};

use crate::foundations::Label;
use crate::introspection::{Location, Tag};
use crate::layout::{Abs, Axes, FixedAlignment, Point, Size, Transform};
use crate::model::Destination;
use crate::text::TextItem;
use crate::visualize::{Color, Curve, FixedStroke, Geometry, Image, Paint, Shape};

/// A finished layout with items at fixed positions.
#[derive(Default, Clone, Hash)]
pub struct Frame {
    /// The size of the frame.
    size: Size,
    /// The baseline of the frame measured from the top. If this is `None`, the
    /// frame's implicit baseline is at the bottom.
    baseline: Option<Abs>,
    /// The items composing this layout.
    items: Arc<LazyHash<Vec<(Point, FrameItem)>>>,
    /// The hardness of this frame.
    ///
    /// Determines whether it is a boundary for gradient drawing.
    kind: FrameKind,
}

/// Constructor, accessors and setters.
impl Frame {
    /// Create a new, empty frame.
    ///
    /// Panics if the size is not finite.
    #[track_caller]
    pub fn new(size: Size, kind: FrameKind) -> Self {
        assert!(size.is_finite());
        Self {
            size,
            baseline: None,
            items: Arc::new(LazyHash::new(vec![])),
            kind,
        }
    }

    /// Create a new, empty soft frame.
    ///
    /// Panics if the size is not finite.
    #[track_caller]
    pub fn soft(size: Size) -> Self {
        Self::new(size, FrameKind::Soft)
    }

    /// Create a new, empty hard frame.
    ///
    /// Panics if the size is not finite.
    #[track_caller]
    pub fn hard(size: Size) -> Self {
        Self::new(size, FrameKind::Hard)
    }

    /// Sets the frame's hardness.
    pub fn set_kind(&mut self, kind: FrameKind) {
        self.kind = kind;
    }

    /// Sets the frame's hardness builder-style.
    pub fn with_kind(mut self, kind: FrameKind) -> Self {
        self.kind = kind;
        self
    }

    /// Whether the frame is hard or soft.

/// output file name that ends with `.svg`.
///
/// If your document has more than one page, Typst will create multiple image
/// files. The output file name must then be a template string containing at
/// least one of
/// - `[{p}]`, which will be replaced by the page number
/// - `[{0p}]`, which will be replaced by the zero-padded page number (so that
///   all numbers have the same length)
/// - `[{t}]`, which will be replaced by the total number of pages
///
/// When exporting to SVG, you have the following configuration options:
///
/// - Which pages to export by specifying `--pages` followed by a
///   comma-separated list of numbers or dash-separated number ranges. Ranges
///   can be half-open. Example: `2,3,7-9,11-`.
///
/// == Web App <web-app>
/// Click "File" > "Export as" > "SVG" or click the downwards-facing arrow next
/// to the quick download button and select "Export as SVG". When exporting to
/// SVG, you have the following configuration options:
///
/// - Which pages to export. Valid options are "All pages", "Current page", and
///   "Custom ranges". Custom ranges are a comma-separated list of numbers or
///   dash-separated number ranges. Ranges can be half-open. Example:
///   `2,3,7-9,11-`.
#[elem(name = "svg", title = "SVG", since = "unreleased", Construct)]
pub struct SvgFormat {
    /// Whether to pretty-print the produced SVG file.
    ///
    /// This formats the output in a more human-readable, but less
    /// space-efficient way.
    #[default(false)]
    pub pretty: bool,
}

impl FormatElement for SvgFormat {
    type Options = SvgFormatOptions;
}

impl Construct for SvgFormat {
    fn construct(_: &mut Engine, args: &mut Args) -> SourceResult<Content> {
        bail!(args.span, "cannot be constructed manually")
    }
}

/// Document settings for SVG export.
#[derive(Debug, Default, Clone, Eq, PartialEq, Hash)]
pub struct SvgFormatOptions<F: Fields = Complete> {
    pub pretty: F::Value<SvgFormat, { SvgFormat::pretty.index() }>,
}

impl SvgFormatOptions<Partial> {
    /// Resolves the [`Partial`] options to [`Complete`] ones, given defaults.
    pub fn resolve(&self, default: &SvgFormatOptions) -> SvgFormatOptions {
        SvgFormatOptions {
            pretty: Partial::resolve(self.pretty, default.pretty),
        }
    }
}

